import {LocalStore} from './src/storage.js';
import {defaults,allGames,lastGame,activeRecord,beginGame,commandGame,endSession,assignPlayers,removePlayer,playerStats} from './src/app-model.js';
import {parseDescription} from './src/description.js';
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={play:'M8 5l11 7-11 7z',sessions:'M5 4h14v17H5z M8 2v4 M16 2v4 M8 10h8 M8 14h5',players:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M18 8a3 3 0 0 1 0 6 M22 21v-2a4 4 0 0 0-3-4',stats:'M4 20V10 M12 20V4 M20 20v-8',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0z M5 10v2a7 7 0 0 0 14 0v-2 M12 19v3 M8 22h8',arrow:'M5 12h14 M13 6l6 6-6 6',undo:'M9 5L3 11l6 6 M3 11h11a6 6 0 0 1 6 6',close:'M6 6l12 12 M18 6L6 18',plus:'M12 5v14 M5 12h14',check:'M5 12l4 4L19 6',flip:'M3 7h17l-4-4 M21 17H4l4 4',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4',star:'M12 3l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',more:'M5 12h.01 M12 12h.01 M19 12h.01',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.play}"/></svg>`;
const button=(label,action,cls='btn',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const uuid=()=>crypto.randomUUID(), now=()=>new Date().toISOString();
const storage=new LocalStore();let data,busy=false,selectedSession=null,setup=null,speech=null,toastTimer,redoTimer,redoVisible=false,channel;
let currentTab='play';
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function duration(r){const mins=Math.max(0,Math.floor(((r.core.end?Date.parse(r.core.end):Date.now())-Date.parse(r.core.start))/60000));return mins>=60?`${Math.floor(mins/60)}h ${mins%60}m`:`${mins}m`;}
const title=r=>r.core.title||'Open play';
const gameLabel=g=>g.profile.scoring==='side-out'?'Traditional side-out':g.profile.scoring==='rally'?'Rally scoring · USAP 2026':'Simple score';
const names=(r,g,t)=>g.config.teams[t].map(id=>r.names[id]||'Guest').join(' + ');
const nameFor=(r,id)=>r.names[id]||'Guest';
const live=()=>activeRecord(data);
const selected=()=>data.sessions.find(r=>r.core.id===selectedSession)||live();
function modal(title,body){stopSpeech();$('#modal-body').innerHTML=`<div class="modal-head"><h2 id="dialog-title">${title}</h2>${button(icon('close'),'close','icon-btn','aria-label="Close dialog"')}</div>${body}`;$('#modal').setAttribute('aria-labelledby','dialog-title');if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){stopSpeech();$('#modal').close();}
function stopSpeech(){if(speech){const old=speech;speech=null;old.abort();}}
function errorInModal(message){let p=$('#modal-error');if(!p){p=document.createElement('p');p.id='modal-error';p.className='error';p.setAttribute('role','alert');$('#modal-body').append(p);}p.textContent=message;}
async function commit(next){
  const saved=await storage.save(next,data.revision);data=saved;channel?.postMessage({revision:data.revision});
}
async function run(fn){if(busy)return;busy=true;document.body.classList.add('busy');try{await fn();}catch(e){if(e.code==='CONFLICT'){data=await storage.read();render();}if($('#modal').open)errorInModal(e.message);else toast(e.message);}finally{busy=false;document.body.classList.remove('busy');}}
function go(tab){closeModal();location.hash=tab;if(currentTab===tab)render();}
function sessionRow(r){const date=new Date(r.core.start),count=allGames(r).filter(g=>g.state.status==='completed').length;return `<button class="session-row" data-action="session" data-id="${r.core.id}"><span class="datebox">${date.toLocaleDateString(undefined,{month:'short'})}<strong>${date.getDate()}</strong></span><span class="grow"><h3>${esc(title(r))}</h3><p>${esc(r.venue||'No venue')} · ${count} ${count===1?'game':'games'} · ${duration(r)}</p></span>${r.core.status==='active'?'<span class="tag live">Active</span>':icon('arrow')}</button>`;}
function header(eyebrow,heading,sub='',action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div>${action}</div>`;}
function playPage(){const a=live();return `${header('YOUR COURT. YOUR GAME.','Let’s play.','Less setup. More pickleball.')} ${a?`<div class="card row between spacer"><div><span class="tag live">Session in progress</span><h3 class="spacer">${esc(title(a))}</h3><p class="subtitle">${duration(a)} · Last saved score ${lastGame(a)?.state.points.join('–')||'0–0'}</p></div>${button('Resume game '+icon('arrow'),'resume','btn primary')}</div><div class="spacer"></div>`:''}<div class="grid"><section class="card hero"><div class="court-art" aria-hidden="true"></div><div class="ball" aria-hidden="true">∴</div><div><div class="eyebrow">READY WHEN YOU ARE</div><h2>A little less setup.<br>A lot more play.</h2><p>Tap who won the rally. We’ll keep track of the rest.</p></div><div class="row spacer">${button(a?'Resume session':'Quick Play '+icon('arrow'),a?'resume':'quick','btn light')}${button('Set up game','setup','btn outline light',a?'disabled':'')}</div><small style="color:#d6e2cf;margin-top:12px">Doubles · Side-out · First to 11 · Win by 2</small></section><section class="card voice-card"><div class="row between"><span class="icon-circle">${icon('mic')}</span><span class="tag">FAST SETUP</span></div><h2>Say it. Then play it.</h2><blockquote>“John and Jack versus Liam and Ephram. John serving first.”</blockquote><p class="muted" style="font-size:13px">Describe your game. Check the teams. Start playing.</p>${button('Describe your game '+icon('arrow'),'describe','btn primary full',a&&lastGame(a)?.state.status==='playing'?'disabled':'')}</section></div><div class="section-head"><h2>Recent sessions</h2>${button('View all '+icon('arrow'),'sessions','text-button')}</div>${data.sessions.length?`<div class="list">${data.sessions.slice(0,3).map(sessionRow).join('')}</div>`:`<div class="empty">${icon('sessions')}<h3>Your next outing starts here.</h3><p>Games stay together in one session, even when partners change.</p></div>`}<div class="local-note">${icon('lock')}<span>Private development build. Sessions save in this browser on this device. Cloud sync and workout recording are not connected yet.</span></div>`;}
function miniCourt(r,g){const order=[g.state.screenLeftTeam,1-g.state.screenLeftTeam];return `<div class="court" role="img" aria-label="Legal starting service positions. ${esc(nameFor(r,g.state.servingSlotId))} serves from the ${g.state.serviceSide}.">${order.map((t,idx)=>`<div class="court-half">${(idx===0?['left','right']:['right','left']).map(side=>{const p=g.state.positions.find(p=>p.team===t&&p.side===side);return `<div class="position ${p?.slotId===g.state.servingSlotId?'serving':''}">${p?`<strong>${p.slotId===g.state.servingSlotId?'● ':''}${esc(nameFor(r,p.slotId))}</strong><small>${p.slotId===g.state.servingSlotId?'SERVING · ':''}${side.toUpperCase()}</small>`:''}</div>`;}).join('')}</div>`).join('')}</div><p class="court-caption">Service positions, facing the net. ● marks the server. Players may move after the serve.</p>`;}
function scorePage(){const r=live();if(!r)return playPage();const g=lastGame(r),s=g.state,done=s.status==='completed',abandoned=s.status==='abandoned',order=[s.screenLeftTeam,1-s.screenLeftTeam];return `<div class="score-head"><div><div class="eyebrow">LIVE SESSION · <span data-elapsed="${r.core.id}">${duration(r)}</span></div><h1>${esc(title(r))}</h1><p class="subtitle">Game ${allGames(r).length} · ${gameLabel(g)} · ${g.config.target}, win by ${g.config.winBy}</p></div>${button(icon('more'),'game-menu','icon-btn','aria-label="Game options"')}</div>${done?`<div class="complete-banner"><div class="eyebrow" style="color:#d7e7ca">GAME COMPLETE</div><h2>${esc(names(r,g,s.winner))} win ${s.points[s.winner]}–${s.points[1-s.winner]}</h2><p>Accidental final rally? Undo is still right below the score.</p></div>`:''}${abandoned?'<div class="warning">Game ended early. It will not count as a win or loss.</div>':''}<div class="live-grid"><section><p class="score-guide">${done?'FINAL SCORE':abandoned?'INCOMPLETE GAME':'TAP THE TEAM THAT WON THE RALLY'}</p><div class="scoreboard">${order.map(t=>`<button class="score-target ${t===1?'team-b':''}" data-action="rally" data-team="${t}" ${s.status!=='playing'?'disabled':''} aria-label="${esc(names(r,g,t))} won the rally. Current score ${s.points[t]}"><span class="team-label">TEAM ${t+1}</span><strong class="score-number">${s.points[t]}</strong><span class="names">${esc(names(r,g,t))}</span><span class="server-badge">${s.servingTeam===t&&s.status==='playing'?`● SERVING${s.serverNumber?' · SERVER '+s.serverNumber:''}`:s.gamePointTeams.includes(t)?'GAME POINT':'&nbsp;'}</span></button>`).join('')}</div><div class="score-tools">${button(icon('undo')+' Undo last rally','undo','btn outline',!s.effectiveRallyIds.length||abandoned?'disabled':'')}${s.redoEventId&&redoVisible?button('Redo','redo','btn outline'):''}</div>${s.status==='playing'?`<div class="serve-call" aria-live="polite"><strong>${s.scoreCall.join(' – ')}</strong><p>${esc(nameFor(r,s.servingSlotId))} serves · ${s.serviceSide} service box${s.openingServiceTurn?' · opening server':''}</p></div>`:`<div class="row">${abandoned?button('Resume this game','reopen','btn outline full'):''}${button('Start next game '+icon('arrow'),'next','btn primary full')}${button('Finish session','finish','btn outline full')}</div>`}<p class="privacy" style="text-align:center;margin-top:15px">Each rally is saved on this device before the score changes.</p></section><aside class="stack"><section class="card"><div class="row between"><h3>Who serves?</h3>${button(icon('flip'),'flip','icon-btn','aria-label="Flip court view"')}</div>${miniCourt(r,g)}${button(icon('flip')+' Flip court view','flip','text-button full')}</section><section class="card"><div class="eyebrow">THIS OUTING</div><div class="row between"><h3>${allGames(r).filter(x=>x.state.status==='completed').length} games complete</h3><span class="tag" data-elapsed="${r.core.id}">${duration(r)}</span></div><p class="subtitle">${esc(r.venue||'No venue added')}</p>${button('Session details','live-details','text-button')}</section></aside></div>`;}
function sessionsPage(){return `${header('YOUR TIME ON COURT','Sessions','Every outing, with every game together.')}${data.sessions.length?`<div class="list">${data.sessions.map(sessionRow).join('')}</div>`:'<div class="empty"><h3>No sessions yet.</h3><p>Start with Quick Play. Your games will appear here.</p></div>'}`;}
function sessionDetail(){const r=selected();if(!r)return sessionsPage();const games=allGames(r),completed=games.filter(g=>g.state.status==='completed');return `${button('← Sessions','sessions','text-button')}${header(r.core.status==='active'?'SESSION IN PROGRESS':'SESSION COMPLETE',esc(title(r)),`${new Date(r.core.start).toLocaleString()} · ${esc(r.venue||'No venue')}`,r.core.status==='active'?button('Resume','resume','btn primary'):button(icon('more'),'session-menu','icon-btn','aria-label="Session options"'))}<div class="stats-grid"><div class="stat"><strong>${duration(r)}</strong><span>Session duration</span></div><div class="stat"><strong>${completed.length}</strong><span>Completed games</span></div><div class="stat"><strong>${new Set(Object.values(r.assignments).filter(Boolean)).size}</strong><span>Named players</span></div></div><div class="section-head"><h2>Games</h2></div><div class="list">${games.map((g,i)=>`<article class="card"><div class="row between"><span class="tag">Game ${i+1} · ${g.state.status==='completed'?'Complete':g.state.status==='playing'?'In progress':'Ended early'}</span><span class="result-score">${g.state.points.join(' – ')}</span></div><p class="spacer break">${esc(names(r,g,0))}<span class="muted"> vs </span>${esc(names(r,g,1))}</p><p class="field-hint">${gameLabel(g)} · ${g.config.target} points · Win by ${g.config.winBy}</p>${button('Assign players','assign','text-button',`data-game="${g.config.gameId}"`)}</article>`).join('')}</div><div class="local-note">${icon('lock')}<span>Saved on this device. Workout: not recorded. PaddleLog: not connected.</span></div>${r.core.status==='completed'?`<div class="row spacer">${button('Rematch '+icon('arrow'),'rematch','btn primary',live()?'disabled':'')}${button('Done','play','btn outline')}</div>`:''}`;}
function playersPage(){const players=[...data.players].sort((a,b)=>Number(b.favorite)-Number(a.favorite)||(b.lastUsed||'').localeCompare(a.lastUsed||'')||a.name.localeCompare(b.name));return `${header('GOOD GAMES. FAMILIAR FACES.','Players','Keep your regular crew one tap away.',button(icon('plus')+' Add','add-player','btn primary'))}${players.length?`<div class="list">${players.map(p=>{const stats=playerStats(data,p.id);return `<article class="card player-row"><span class="avatar">${esc(p.name.slice(0,2).toUpperCase())}</span><div class="grow"><h3>${esc(p.name)} ${data.prefs.selfId===p.id?'<span class="tag">You</span>':''}</h3><p>${stats.games} games · ${stats.wins} wins · ${stats.losses} losses</p></div>${button(icon('star'),'favorite',`icon-btn ${p.favorite?'is-favorite':''}`,`data-id="${p.id}" aria-label="${p.favorite?'Unfavorite':'Favorite'} ${esc(p.name)}" aria-pressed="${!!p.favorite}"`)}${button(icon('more'),'edit-player','icon-btn',`data-id="${p.id}" aria-label="Edit ${esc(p.name)}"`)}</article>`;}).join('')}</div>`:`<div class="empty">${icon('players')}<h3>Bring your people.</h3><p>Save a name, not an account. Guests can always play too.</p>${button('Add your first player','add-player','btn primary spacer')}</div>`}<div class="local-note">${icon('lock')}<span>Your player library is private to this device. Adding a name never invites someone or shares your history.</span></div>`;}
function statsPage(){const self=data.prefs.selfId,stats=playerStats(data,self),total=data.sessions.flatMap(allGames).filter(g=>g.state.status==='completed').length;return `${header('A LITTLE PERSPECTIVE','Your stats','Results from the games you record.')}<div class="card form-stack"><label>Your player<select id="stats-player"><option value="">Choose yourself to see your results</option>${data.players.map(p=>`<option value="${p.id}" ${p.id===self?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${self?`<div class="stats-grid"><div class="stat"><strong>${stats.wins}</strong><span>Wins</span></div><div class="stat"><strong>${stats.losses}</strong><span>Losses</span></div><div class="stat"><strong>${stats.games?Math.round(stats.wins/stats.games*100):0}%</strong><span>Win percentage</span></div></div><p class="muted">${stats.games} recorded games · ${stats.differential>0?'+':''}${stats.differential} point differential</p>`:'<p class="muted">Assign your name to completed games to include them in your personal results.</p>'}</div><div class="section-head"><h2>All recorded play</h2></div><div class="stats-grid"><div class="stat"><strong>${data.sessions.length}</strong><span>Sessions</span></div><div class="stat"><strong>${total}</strong><span>Complete games</span></div><div class="stat"><strong>${data.players.length}</strong><span>Saved players</span></div></div><p class="privacy spacer">Unfinished games do not count as wins or losses. These are recorded results, not a skill rating.</p>`;}
function settingsPage(){return `${header('MAKE IT YOURS','Settings','A simple start, every time.')}<div class="stack"><section class="card"><h2>Your data</h2><p class="subtitle">This preview saves sessions and players in this browser. Clearing website data removes them. Cloud sync is coming in a later build.</p><div class="row spacer">${button('Export backup','export','btn primary')}${button('Request persistent storage','persist','btn outline')}</div><p class="field-hint">Backup contains your session history, names, and rally journals. Keep it private. Restore tooling is planned.</p><p class="field-hint">Scoring works without internet while the page stays open. Reopening the app currently requires a connection.</p></section><section class="card"><h2>Game defaults</h2><p class="subtitle">Your last chosen format, target, and win-by are remembered for game setup. Quick Play always starts traditional doubles to 11, win by 2.</p></section><section class="card"><h2>Voice setup</h2><p class="subtitle">Tap the microphone to describe the teams and first server. Review the result before starting. You can always type or use your keyboard’s dictation.</p><p class="privacy spacer">Speech recognition availability depends on your browser. Its speech provider may process audio online. Pickle Point does not store audio or transcripts.</p></section><section class="card"><h2>Suite connections</h2><p class="subtitle">LeewayPB sign-in, PaddleLog, and workout recording are planned. This build has no connected accounts or billing.</p></section></div>`;}
function render(){if(!data)return;const route=location.hash.slice(1)||'play';currentTab=route;const activeNav=['score','detail'].includes(route)?(route==='detail'?'sessions':'play'):route;$('#nav').innerHTML=['play','sessions','players','stats','settings'].map(n=>`<a href="#${n}" class="${activeNav===n?'active':''}" ${activeNav===n?'aria-current="page"':''}>${icon(n)}<span>${n[0].toUpperCase()+n.slice(1)}</span></a>`).join('');$('#main').innerHTML=({play:playPage,score:scorePage,sessions:sessionsPage,detail:sessionDetail,players:playersPage,stats:statsPage,settings:settingsPage}[route]||playPage)();}
function setupState(source=null){const g=source&&lastGame(source);const count=g?.profile.discipline==='singles'?1:2;return {settings:g?{profileId:g.config.profileId,target:g.config.target,winBy:g.config.winBy,startingTeam:g.config.startingTeam,switchEndsAt:g.config.switchEndsAt}:{...data.prefs},names:g?g.config.teams.flat().map(id=>source.assignments[id]?nameFor(source,id):''):Array(count*2).fill(''),title:source?title(source):'Open play',venue:source?.venue||'',warnings:[]};}
function showSetup(){const s=setup.settings,count=s.profileId.endsWith('singles')?1:2;setup.names=Array.from({length:count*2},(_,i)=>setup.names[i]||'');const recent=[...data.players].sort((a,b)=>Number(b.favorite)-Number(a.favorite)||(b.lastUsed||'').localeCompare(a.lastUsed||''));modal(live()?'Next game':'Who’s playing?',`<form id="setup-form" class="form-stack">${setup.warnings.map(w=>`<div class="warning">${esc(w)}</div>`).join('')}<p class="muted" style="font-size:13px">First player on each team starts on the right. Add names now or keep guests.</p>${recent.length?`<div><div class="eyebrow">FAVORITES & RECENT</div><div class="chips">${recent.slice(0,10).map(p=>button(esc(p.name),'pick-player',`chip ${setup.names.includes(p.name)?'selected':''}`,`data-id="${p.id}"`)).join('')}</div></div>`:''}<datalist id="player-names">${data.players.map(p=>`<option value="${esc(p.name)}">`).join('')}</datalist><div class="form-grid">${[0,1].map(t=>`<div class="team-setup ${t?'orange':''}"><h3>Team ${t+1}</h3>${Array.from({length:count},(_,i)=>{const index=t*count+i;return `<label>${i===0?'Right · first server':'Left · partner'}<input name="player${index}" maxlength="60" autocomplete="off" list="player-names" value="${esc(setup.names[index])}" placeholder="Guest ${index+1}"></label>`;}).join('')}</div>`).join('')}</div><div class="row">${button('Swap partners','swap-partners','btn small outline',count!==2?'disabled':'')}${button('Randomize teams','randomize','btn small outline')}</div><div class="form-grid"><label>Scoring<select name="profile">${[['usap-2026-side-out-doubles','Traditional · doubles'],['usap-2026-side-out-singles','Traditional · singles'],['usap-2026-rally-doubles','USAP 2026 rally · doubles'],['usap-2026-rally-singles','USAP 2026 rally · singles']].map(([v,l])=>`<option value="${v}" ${v===s.profileId?'selected':''}>${l}</option>`).join('')}</select></label><label>First serving team<select name="starting"><option value="0" ${s.startingTeam===0?'selected':''}>Team 1 · right player</option><option value="1" ${s.startingTeam===1?'selected':''}>Team 2 · right player</option></select></label><label>Play to<input name="target" type="number" min="1" max="100" required value="${s.target}"></label><label>Win by<input name="winBy" type="number" min="1" max="10" required value="${s.winBy}"></label><label class="wide">Switch ends at<select name="switch"><option value="">No automatic switch</option>${[6,8,11].map(n=>`<option value="${n}" ${s.switchEndsAt===n?'selected':''}>First team reaches ${n}</option>`).join('')}</select></label></div>${!live()?`<div class="form-grid"><label>Session name<input name="title" maxlength="200" value="${esc(setup.title)}"></label><label>Venue · optional<input name="venue" maxlength="150" value="${esc(setup.venue)}" placeholder="Where are you playing?"></label></div>`:''}<label class="row"><input type="checkbox" name="savePlayers" checked>Save new names to my player library</label><div class="setup-actions">${button('Cancel','close','btn outline')}<button type="submit" class="btn primary">Start playing ${icon('arrow')}</button></div><p id="modal-error" class="error" role="alert"></p></form>`);}
function captureSetup(){const form=$('#setup-form');if(!form)return;const f=new FormData(form);setup.names=Array.from(form.querySelectorAll('input[name^="player"]')).map(x=>x.value.trim());setup.settings={profileId:f.get('profile'),target:Number(f.get('target')),winBy:Number(f.get('winBy')),startingTeam:Number(f.get('starting')),switchEndsAt:f.get('switch')?Number(f.get('switch')):null};setup.title=f.get('title')||setup.title;setup.venue=f.get('venue')||setup.venue;}
async function startConfigured(saveNames=true){
  let d=structuredClone(data);const players=setup.names.map(name=>{if(!name.trim())return null;let p=d.players.find(p=>p.name.toLocaleLowerCase()===name.trim().toLocaleLowerCase());if(!p){p={id:uuid(),name:name.trim(),favorite:false,lastUsed:now()};if(saveNames)d.players.push(p);}return p;});
  if(new Set(setup.names.filter(Boolean).map(n=>n.toLocaleLowerCase())).size!==setup.names.filter(Boolean).length)throw new Error('Give each player a distinct name or leave the position as a guest.');
  d=beginGame(d,{sessionId:uuid(),matchId:uuid(),gameId:uuid(),at:now(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC',title:setup.title,venue:setup.venue,settings:setup.settings,players});await commit(d);closeModal();go('score');navigator.storage?.persist?.().catch(()=>{});
}
function describe(){modal('Describe your game',`<form id="description-form" class="form-stack"><p class="muted">Tell us the teams, the format, and who serves first.</p><label>Your game<textarea id="description" rows="4" maxlength="600" required placeholder="John and Jack vs Liam and Ephram in a normal game, John serving first"></textarea></label><div class="row">${button(icon('mic')+' Use microphone','mic','btn outline','id="mic-button"')}${button('Try example','example','text-button')}</div><p id="speech-status" class="privacy" aria-live="polite">Your browser’s speech provider may process audio online. We don’t store audio or your description. Typing and keyboard dictation also work.</p><button type="submit" class="btn primary full">Preview game ${icon('arrow')}</button><p class="field-hint">“Normal game” means side-out to 11, win by 2. Also try “rally scoring to 15, win by 2”. Review unfamiliar formats manually.</p><p id="modal-error" class="error" role="alert"></p></form>`);}
function startSpeech(){if(speech){speech.stop();return;}const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){$('#speech-status').textContent='This browser does not offer in-page voice input. Use your keyboard’s microphone or type the description.';$('#description').focus();return;}const r=new Recognition();speech=r;r.lang='en-US';r.interimResults=true;r.continuous=false;const area=$('#description'),status=$('#speech-status'),mic=$('#mic-button');r.onstart=()=>{status.textContent='Listening… Describe your game, then tap Stop.';mic.innerHTML=icon('mic')+' Stop listening';mic.classList.add('listening');};r.onresult=e=>{area.value=Array.from(e.results).map(x=>x[0].transcript).join(' ');};r.onerror=e=>{status.textContent=({ 'not-allowed':'Microphone access was denied. Type your description or use keyboard dictation.',network:'Speech service is unavailable. Type your description or try again when connected.','no-speech':'No speech detected. Try again, or type your description.'}[e.error]||'Voice input stopped. Your typed description is still available.');};r.onend=()=>{if(speech===r)speech=null;mic.innerHTML=icon('mic')+' Use microphone';mic.classList.remove('listening');if(status.textContent.startsWith('Listening'))status.textContent='Check the words above, then preview your game.';};try{r.start();}catch{speech=null;status.textContent='Voice input is unavailable. Type or use keyboard dictation.';}}
async function scoreCommand(type,extra={}){const r=live(),g=lastGame(r);const result=commandGame(data,r.core.id,g.config.gameId,{type,...extra,eventId:uuid(),at:now(),expectedRevision:g.state.headRevision,hostEpoch:g.config.hostEpoch});await commit(result.data);redoVisible=type==='UndoRally';clearTimeout(redoTimer);if(redoVisible)redoTimer=setTimeout(()=>{redoVisible=false;if(currentTab==='score')render();},6000);render();if(result.effects.includes('switch-ends'))toast('Switch ends — court orientation updated.');else if(result.effects.includes('second-server'))toast('Second server');else if(result.effects.includes('side-out'))toast('Side out');else if(type==='UndoRally')toast('Last rally undone');}
function playerForm(id){const p=data.players.find(x=>x.id===id);modal(p?'Edit player':'Add a player',`<form id="player-form" data-id="${p?.id||''}" class="form-stack"><label>Name<input name="name" maxlength="60" required value="${esc(p?.name||'')}" autocomplete="off"></label><label class="row"><input type="checkbox" name="self" ${p?.id===data.prefs.selfId?'checked':''}>This is me</label><button type="submit" class="btn primary full">Save player</button>${p?button('Delete player and anonymize their history','delete-player','btn danger',`data-id="${p.id}"`):''}<p id="modal-error" class="error" role="alert"></p></form>`);}
function assignForm(gameId){const r=selected(),g=allGames(r).find(g=>g.config.gameId===gameId);modal('Players in this game',`<form id="assign-form" data-game="${gameId}" class="form-stack"><p class="muted">Assign saved players to the existing positions. Scores and service order stay intact.</p>${g.config.teams.flat().map((slot,i)=>`<label>Team ${Math.floor(i/g.config.teams[0].length)+1} · ${esc(nameFor(r,slot))}<select name="slot${i}"><option value="">Guest</option>${data.players.map(p=>`<option value="${p.id}" ${r.assignments[slot]===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>`).join('')}<p class="field-hint">Need a new name? Add it in Players, then return here.</p><button type="submit" class="btn primary full">Save players</button><p id="modal-error" class="error" role="alert"></p></form>`);}
async function finish(){const r=live();await commit(endSession(data,r.core.id,now()));selectedSession=r.core.id;closeModal();go('detail');}
function confirmDialog(heading,text,action,id=''){modal(heading,`<p>${text}</p><div class="row spacer">${button('Cancel','close','btn outline')}${button('Confirm',action,'btn danger',id?`data-id="${id}"`:'')}</div>`);}
function exportData(raw=data){const url=URL.createObjectURL(new Blob([JSON.stringify(raw,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`pickle-point-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;
  if(['play','sessions','players','stats','settings'].includes(action)){go(action);return;}
  if(action==='close'){closeModal();return;}
  if(action==='describe'){describe();return;}
  if(action==='mic'){startSpeech();return;}
  if(action==='example'){$('#description').value="Alright, it's John and Jack vs Liam and Ephram in a normal game, John serving first";return;}
  if(action==='resume'){go('score');return;}
  if(action==='session'){selectedSession=b.dataset.id;go('detail');return;}
  if(action==='live-details'){selectedSession=live().core.id;go('detail');return;}
  if(action==='setup'){setup=setupState();showSetup();return;}
  if(action==='next'||action==='rematch'){setup=setupState(action==='next'?live():selected());showSetup();return;}
  if(action==='pick-player'){captureSetup();const p=data.players.find(p=>p.id===b.dataset.id),index=setup.names.indexOf(p.name);if(index>=0)setup.names[index]='';else{const empty=setup.names.findIndex(n=>!n);if(empty>=0)setup.names[empty]=p.name;else{toast('Both teams are full. Clear a position first.');return;}}showSetup();return;}
  if(action==='swap-partners'||action==='randomize'){captureSetup();if(action==='swap-partners')[setup.names[1],setup.names[3]]=[setup.names[3],setup.names[1]];else for(let i=setup.names.length-1;i>0;i--){const j=crypto.getRandomValues(new Uint32Array(1))[0]%(i+1);[setup.names[i],setup.names[j]]=[setup.names[j],setup.names[i]];}showSetup();return;}
  if(action==='add-player'||action==='edit-player'){playerForm(b.dataset.id);return;}
  if(action==='assign'){assignForm(b.dataset.game);return;}
  if(action==='game-menu'){modal('Game options',`<div class="form-stack">${button('Describe the next game','describe','btn outline',lastGame(live()).state.status==='playing'?'disabled':'')}${button('End current game early','abandon-confirm','btn danger',lastGame(live()).state.status!=='playing'?'disabled':'')}<p class="privacy">An early-ended game is saved as incomplete and excluded from wins and losses. You can then finish the session.</p></div>`);return;}
  if(action==='abandon-confirm'){confirmDialog('End this game early?','The score will be saved as incomplete. You can resume this game before starting another.','abandon');return;}
  if(action==='finish'){confirmDialog('Finish this session?','All games will be saved together. Check the final score first: rally correction is available before you finish the session.','finish-confirm');return;}
  if(action==='session-menu'){const r=selected();modal('Session options',`<div class="form-stack">${button('Export all history','export','btn outline')}${button('Delete this session','delete-session-confirm','btn danger',`data-id="${r.core.id}"`)}</div>`);return;}
  if(action==='delete-session-confirm'){confirmDialog('Delete this session?','This removes its games and rally history from this device. It cannot be undone. No other application is connected.','delete-session',b.dataset.id);return;}
  if(action==='delete-player'){confirmDialog('Delete this player?','Their name and player link will be removed from all local sessions. Recorded scores remain with anonymous guest labels.','delete-player-confirm',b.dataset.id);return;}
  run(async()=>{
    if(action==='quick'){setup={settings:{...defaults},names:['','','',''],title:'Open play',venue:''};await startConfigured(false);}
    if(action==='rally')await scoreCommand('RallyWon',{winner:Number(b.dataset.team)});
    if(action==='undo')await scoreCommand('UndoRally');
    if(action==='redo')await scoreCommand('RedoRally');
    if(action==='flip')await scoreCommand('FlipView');
    if(action==='reopen')await scoreCommand('ReopenGame');
    if(action==='abandon'){await scoreCommand('AbandonGame');closeModal();}
    if(action==='finish-confirm')await finish();
    if(action==='favorite'){const d=structuredClone(data),p=d.players.find(p=>p.id===b.dataset.id);p.favorite=!p.favorite;await commit(d);render();}
    if(action==='delete-player-confirm'){await commit(removePlayer(data,b.dataset.id));closeModal();render();}
    if(action==='delete-session'){const d=structuredClone(data);d.sessions=d.sessions.filter(r=>r.core.id!==b.dataset.id);await commit(d);selectedSession=null;go('sessions');}
    if(action==='export'){exportData();toast('Backup exported. Keep it somewhere safe.');}
    if(action==='persist'){const granted=await navigator.storage?.persist?.();toast(granted?'Persistent storage is enabled. Keep backups too.':'Your browser controls storage retention. Export backups regularly.');}
  });
});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;run(async()=>{
  if(form.id==='description-form'){stopSpeech();const parsed=parseDescription($('#description').value);setup={settings:{profileId:parsed.profileId,target:parsed.target,winBy:parsed.winBy,startingTeam:parsed.startingTeam,switchEndsAt:null},names:parsed.teams.flat(),title:'Open play',venue:'',warnings:parsed.warnings};showSetup();}
  if(form.id==='setup-form'){captureSetup();await startConfigured(new FormData(form).has('savePlayers'));}
  if(form.id==='player-form'){const f=new FormData(form),name=f.get('name').trim();if(!name)throw new Error('Enter a player name.');const id=form.dataset.id||uuid(),d=structuredClone(data);if(d.players.some(p=>p.id!==id&&p.name.toLocaleLowerCase()===name.toLocaleLowerCase()))throw new Error('That name is already saved. Add a last initial for a different person.');let p=d.players.find(p=>p.id===id);if(p)p.name=name;else d.players.push({id,name,favorite:false,lastUsed:null});if(f.has('self'))d.prefs.selfId=id;else if(d.prefs.selfId===id)d.prefs.selfId=null;await commit(d);closeModal();render();}
  if(form.id==='assign-form'){const f=new FormData(form),ids=Array.from(form.querySelectorAll('select')).map(s=>f.get(s.name));await commit(assignPlayers(data,selected().core.id,form.dataset.game,ids));closeModal();render();}
});});
document.addEventListener('change',e=>{if(e.target.matches('#setup-form select[name="profile"]')){captureSetup();showSetup();}if(e.target.id==='stats-player')run(async()=>{const d=structuredClone(data);d.prefs.selfId=e.target.value||null;await commit(d);render();});});
$('#modal').addEventListener('cancel',stopSpeech);window.addEventListener('pagehide',stopSpeech);
window.addEventListener('hashchange',()=>{closeModal();render();});
setInterval(()=>{if(data)document.querySelectorAll('[data-elapsed]').forEach(el=>{const r=data.sessions.find(r=>r.core.id===el.dataset.elapsed);if(r)el.textContent=duration(r);});},15000);
async function refresh(){if(!data||busy)return;try{const latest=await storage.read();if(latest.revision!==data.revision){data=latest;render();toast('Updated from another tab.');}}catch(e){toast(e.message);}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSpeech();else refresh();});
try{await storage.open();data=await storage.read();if('BroadcastChannel'in window){channel=new BroadcastChannel('pickle-point-updates');channel.onmessage=refresh;}render();if(live()&&currentTab==='play')toast('Your saved game is ready to resume.');}catch(e){$('#main').innerHTML=`<section class="card"><h1>Saved data needs attention</h1><p class="subtitle">${esc(e.message)}</p><p class="spacer">Nothing has been reset. Export the stored data before troubleshooting.</p>${button('Export stored data','raw-export','btn primary spacer')}</section>`;document.addEventListener('click',async e=>{if(e.target.closest('[data-action="raw-export"]')){try{exportData(await storage.raw());}catch{toast('Storage could not be read. Try this browser again without clearing its data.');}}});}
